import * as React from "react"
import { cn } from "../lib/utils"

export interface EverleapLogoProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  className?: string
}

export function EverleapLogo({ className, ...props }: EverleapLogoProps) {
  return (
    <img
      src="data:image/png;base64,"
      alt="Everleap Logo"
      className={cn("h-10 w-auto", className)}
      {...props}
    />
  )
}
